	/* @Override */
	public bool isUndefined(Address start, Address end) {
		using (LockHold hold = program.trace.lockRead())
{
			foreach (AddressRange range in program.getAddressFactory().getAddressSet(start, end)) {
				foreach (long s in program.viewport.getOrderedSnaps()) {
					if (!isUndefinedRange(s, range)) {
						return false;
					}
				}
			}
			return true;
		}
	}

